def comps(mat,val,conn=4):
 m,n=mat.shape; seen=set(); out=[]
 dirs=[(-1,0),(1,0),(0,-1),(0,1)] if conn==4 else [(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr,dc)!=(0,0)]
 for r in range(m):
  for c in range(n):
   if mat[r,c]!=val or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dr,dc in dirs:
     p=(x+dr,y+dc)
     if 0<=p[0]<m and 0<=p[1]<n and mat[p]==val and p not in seen:
      seen.add(p);q.append(p)
   out.append(cells)
 return out
